    if (json) console.log(JSON.stringify(out, null, 2));
    else printStatus(out);
    process.exitCode = out.status === "COMPLETE" ? 0 : out.status === "CANCELLED" ? 130 : 2;
  } finally {
    process.off("SIGINT", onSignal);
